def handle(query, state):
    import shlex

    vfs = state.get('files', {})

    def _expand_arithmetic(s):
        """Expand $((expr)) arithmetic in a token.  Only integer arithmetic."""
        import re
        def _eval_arith(m):
            try:
                return str(eval(m.group(1), {'__builtins__': {}}))
            except Exception:
                return m.group(0)
        return re.sub(r'\$\(\(([^)]+)\)\)', _eval_arith, s)

    def run_cmd(argv):
        """Simulate a small set of shell commands against the in-memory VFS."""
        if not argv:
            return ''
        cmd = argv[0]
        args = [_expand_arithmetic(a) for a in argv[1:]]
        if cmd == 'grep':
            # grep <pattern> <file> — simple substring match
            if len(args) < 2:
                return 'grep: usage: grep PATTERN FILE\n'
            pattern, filepath = args[0], args[1]
            content = vfs.get(filepath, '')
            matches = [line for line in content.splitlines() if pattern in line]
            return ('\n'.join(matches) + '\n') if matches else ''
        elif cmd == 'cat':
            out = ''
            for path in args:
                content = vfs.get(path)
                if content is None:
                    out += f'cat: {path}: No such file or directory\n'
                else:
                    out += content
                    if not content.endswith('\n'):
                        out += '\n'
            return out
        elif cmd == 'echo':
            return ' '.join(args) + '\n'
        elif cmd == 'ls':
            path = args[0] if args else '/'
            entries = sorted(k for k in vfs if k.startswith(path))
            return ('\n'.join(entries) + '\n') if entries else 'ls: no entries\n'
        else:
            return f'{cmd}: command not found\n'

    def shell_exec(cmdline):
        """Split on ';' and execute each segment.  No subshell ($(...)) support."""
        output = ''
        for segment in cmdline.split(';'):
            segment = segment.strip()
            if not segment:
                continue
            try:
                argv = shlex.split(segment)
            except ValueError:
                argv = segment.split()
            output += run_cmd(argv)
        return output

    pattern = (query.get('pattern') or [''])[0]
    logfile = (query.get('logfile') or ['/var/log/app.log'])[0]

    if not pattern:
        return 200, {'Content-Type': 'text/plain'}, 'Usage: ?pattern=<term>&logfile=<path>\n'

    # Vulnerable: pattern is concatenated unsanitised into the shell command string.
    output = shell_exec('grep ' + pattern + ' ' + logfile)
    return 200, {'Content-Type': 'text/plain'}, output
